# DBTITLE 1,write a python function to filter out customers who have made more than 5 purchases in the last 6 months
purchases = [
    {"customer_id": 101, "purchase_date": "2026-04-20", "amount": 500},
    {"customer_id": 101, "purchase_date": "2026-05-10", "amount": 200},
    {"customer_id": 101, "purchase_date": "2026-06-15", "amount": 300},
    {"customer_id": 101, "purchase_date": "2026-07-20", "amount": 150},
    {"customer_id": 101, "purchase_date": "2026-08-05", "amount": 400},
    {"customer_id": 101, "purchase_date": "2026-09-12", "amount": 250},

    {"customer_id": 102, "purchase_date": "2026-05-01", "amount": 100},
    {"customer_id": 102, "purchase_date": "2026-06-11", "amount": 200},
    {"customer_id": 102, "purchase_date": "2026-07-18", "amount": 300},

    {"customer_id": 103, "purchase_date": "2026-04-25", "amount": 250},
    {"customer_id": 103, "purchase_date": "2026-05-20", "amount": 350},
    {"customer_id": 103, "purchase_date": "2026-06-25", "amount": 150},
    {"customer_id": 103, "purchase_date": "2026-07-10", "amount": 450},
    {"customer_id": 103, "purchase_date": "2026-08-15", "amount": 550},
    {"customer_id": 103, "purchase_date": "2026-09-20", "amount": 600},
    {"customer_id": 103, "purchase_date": "2026-10-10", "amount": 700},

    {"customer_id": 104, "purchase_date": "2026-02-10", "amount": 300},
    {"customer_id": 104, "purchase_date": "2026-03-15", "amount": 400},
]

currentDate= datetime.date.today()
sixmonthsDate = currentDate - relativedelta(months=6)
sixmonthData=[i for i in purchases if i['purchase_date'] >=str(sixmonthsDate)]

purchaseCount={}
def customerWithMorePurches():
    customer_id = list(set([i['customer_id'] for i in sixmonthData]))
    for j in sixmonthData:
        customer_id= j['customer_id']
        purchaseCount[customer_id] = (
            purchaseCount.get(customer_id, 0) + 1
        )
    result = [
    (i,count) for i,count in purchaseCount.items() if purchaseCount[i] >5
    ]
    return result


print(len(sixmonthData))
print("amountCount",customerWithMorePurches())